// Bounded worker lifecycle: every completion, error and timeout terminates it.
export function workerTask(worker,message,transfer=[],{timeout=30000,schedule=setTimeout,unschedule=clearTimeout}={}){return new Promise((resolve,reject)=>{let settled=false,timer;const finish=(error,value)=>{if(settled)return;settled=true;unschedule(timer);worker.onmessage=worker.onerror=worker.onmessageerror=null;worker.terminate();error?reject(error):resolve(value);};timer=schedule(()=>finish(Error('La operación tardó demasiado. Reducí el tamaño de la imagen.')),timeout);worker.onmessage=e=>e.data?.error?finish(Error(e.data.error)):Array.isArray(e.data?.objects)?finish(null,e.data.objects):finish(Error('La operación devolvió datos inválidos.'));worker.onerror=worker.onmessageerror=()=>finish(Error('No se pudo ejecutar la operación.'));try{worker.postMessage(message,transfer);}catch(error){finish(error);}});}
